'use strict'

const MOVES = {
  ArrowUp: { x: 0, y: -1 },
  ArrowDown: { x: 0, y: 1 },
  ArrowLeft: { x: -1, y: 0 },
  ArrowRight: { x: 1, y: 0 },
}

function start(size) {
  return {
    size,
    body: [{ x: 2, y: 2 }, { x: 1, y: 2 }],
    heading: MOVES.ArrowRight,
    food: { x: 4, y: 2 },
    over: false,
  }
}

function turned(heading, key) {
  const wanted = MOVES[key]
  if (wanted === undefined) return heading
  if (wanted.x === -heading.x && wanted.y === -heading.y) return heading
  return wanted
}

function step(state, key) {
  if (state.over) return state
  const heading = turned(state.heading, key)
  const head = { x: state.body[0].x + heading.x, y: state.body[0].y + heading.y }
  if (head.x < 0 || head.y < 0 || head.x >= state.size || head.y >= state.size) {
    return { ...state, heading, over: true }
  }
  const ate = head.x === state.food.x && head.y === state.food.y
  const body = [head, ...(ate ? state.body : state.body.slice(0, -1))]
  const food = ate ? { x: (head.x * 7 + 3) % state.size, y: (head.y * 5 + 1) % state.size } : state.food
  return { ...state, body, heading, food }
}

module.exports = { start, step }

